const CACHE_TTL_MS = 10 * 60 * 1000;
const UA =
  "Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1";

const URLS                            = {
  chatgpt: "com.openai.chat://",
  gemini: "googlegemini://",
};

// Cloud Code hides the Gemini quota group from clients older than 2.23.
// The old CLI UA only returned the Claude/GPT group, which is often still 100%.
const ANTIGRAVITY_UA = "antigravity/hub/2.23.0 darwin/arm64";

function normalizeCpaBaseUrl(value        )         {
  const clean = String(value || "").trim().replace(/\/+$/, "");
  if (!clean) return "";

  const match = clean.match(
    /^(https?):\/\/(\[[0-9a-f:]+\]|[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?)(?::(\d{1,5}))?$/i
  );
  if (!match) throw new Error("CPA 地址必须是纯主机地址，例如 https://host:port");
  const port = match[3] ? Number(match[3]) : null;
  if (port != null && (port < 1 || port > 65535)) throw new Error("CPA 端口无效");
  return clean;
}

// ---------- Helpers ----------
function clampPct(n     )                {
  if (n == null || Number.isNaN(Number(n))) return null;
  return Math.max(0, Math.min(100, Number(n)));
}

function pctLabel(v     )         {
  if (v == null || Number.isNaN(Number(v))) return "—";
  return `${Math.round(v)}`;
}

function formatResetMs(ms        )         {
  if (ms <= 0) return "即将恢复";
  const days = Math.floor(ms / 86400000);
  const hours = Math.floor((ms % 86400000) / 3600000);
  const mins = Math.floor((ms % 3600000) / 60000);
  if (days > 0) return hours > 0 ? `${days}天${hours}小时后` : `${days}天后`;
  if (hours > 0) return mins > 0 ? `${hours}小时${mins}分后` : `${hours}小时后`;
  return `${Math.max(1, mins)}分钟后`;
}

function parseResetTimeMs(isoOrMs      , description      )                {
  if (isoOrMs != null) {
    let end      ;
    if (typeof isoOrMs === "number") end = new Date(isoOrMs < 1e12 ? isoOrMs * 1000 : isoOrMs);
    else end = new Date(isoOrMs);
    const ms = end.getTime();
    if (!Number.isNaN(ms)) return ms;
  }
  if (description) {
    const src = String(description);
    const d = src.match(/(\d+)\s*days?/i);
    const h = src.match(/(\d+)\s*hours?/i);
    const m = src.match(/(\d+)\s*min/i);
    if (d || h || m) {
      const days = d ? Number(d[1]) : 0;
      const hours = h ? Number(h[1]) : 0;
      const mins = m ? Number(m[1]) : 0;
      return Date.now() + ((days * 24 + hours) * 60 + mins) * 60000;
    }
  }
  return null;
}

function parseResetHint(isoOrMs      , description      )                {
  const ms = parseResetTimeMs(isoOrMs, description);
  if (ms != null) {
    return formatResetMs(ms - Date.now());
  }
  return null;
}

function emptyService(id           , name        , url        , note         )               {
  return {
    id,
    name,
    plan: "",
    remainingPct: null,
    usedPct: null,
    windowLabel: note || "未配置",
    resetHint: "",
    resetAt: null,
    remaining5hPct: null,
    reset5hHint: null,
    reset5hAt: null,
    extra: "",
    url,
    ok: false,
  };
}

// ---------- CPA ----------
async function cpaGet(baseUrl        , apiKey        , path        )               {
  const trustedBaseUrl = normalizeCpaBaseUrl(baseUrl);
  return loadJSON(`${trustedBaseUrl}/v0/management${path}`, {
    headers: { Authorization: `Bearer ${apiKey}` },
  });
}

async function cpaApiCall(baseUrl        , apiKey        , body     )               {
  const trustedBaseUrl = normalizeCpaBaseUrl(baseUrl);
  const normalizedBody = Object.assign({}, body);
  const rawIdx = normalizedBody.authIndex ?? normalizedBody.auth_index;
  if (rawIdx != null) {
    const strIdx = String(rawIdx);
    normalizedBody.auth_index = strIdx;
    normalizedBody.authIndex = strIdx;
  }
  return loadJSON(`${trustedBaseUrl}/v0/management/api-call`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: normalizedBody,
    timeout: 30,
  });
}

function parseApiBody(resp     )      {
  if (!resp) throw new Error("empty api-call");
  const code = Number(resp.status_code ?? resp.statusCode ?? 0);
  let body = resp.body;
  if (typeof body === "string") {
    try {
      body = JSON.parse(body);
    } catch (_) {}
  }
  if (code && code >= 400) {
    const msg = (body && (body.error || body.message || body.msg)) || `HTTP ${code}`;
    const err      = new Error(String(msg));
    err.statusCode = code;
    throw err;
  }
  return body;
}

async function listCpaFiles(cfg        )                     {
  if (!cfg.cpaBaseUrl || !cfg.cpaApiKey) return [];
  const resp = await cpaGet(cfg.cpaBaseUrl, cfg.cpaApiKey, "/auth-files");
  return Array.isArray(resp?.files) ? resp.files : [];
}

function findCpaFiles(files                       , testers          )            {
  const seen = new Set        ();
  const matched            = [];
  for (const f of files || []) {
    if (f.disabled) continue;
    const blob = `${f.provider || ""} ${f.type || ""} ${f.name || ""}`.toLowerCase();
    if (!testers.some((t) => t.test(blob))) continue;
    const index = authIndexOf(f);
    const key = index == null ? `name:${f.name || ""}` : `idx:${index}`;
    if (seen.has(key)) continue;
    seen.add(key);
    matched.push(f);
  }
  return matched;
}

function authIndexOf(file     )                         {
  const value = file?.auth_index ?? file?.authIndex;
  return value == null || value === "" ? null : value;
}

// ---------- Parsers ----------
function prettyChatPlan(plan     )         {
  const raw = String(plan || "");
  const p = raw.toLowerCase();
  if (!p) return "Plus";
  if (p === "plus") return "Plus";
  if (p === "pro") return "Pro";
  if (p === "free") return "Free";
  if (p === "team") return "Team";
  return raw.charAt(0).toUpperCase() + raw.slice(1);
}

function windowLabelFromSeconds(seconds     )         {
  if (!Number.isFinite(seconds)) return "额度";
  if (seconds >= 6 * 24 * 3600) return "本周";
  if (seconds >= 20 * 3600) return `${Math.round(seconds / 86400)}天`;
  const hours = Math.max(1, Math.round(seconds / 3600));
  return `${hours}小时`;
}

function isLatentWindow(win     )          {
  const used = Number(win?.used_percent);
  const resetAfter = Number(win?.reset_after_seconds);
  const limit = Number(win?.limit_window_seconds);
  return used === 0 && Number.isFinite(resetAfter) && Number.isFinite(limit) && resetAfter >= limit;
}

function normalizeUsageWindow(win     )                     {
  const usedPercent = Number(win?.used_percent);
  if (!Number.isFinite(usedPercent)) return null;
  const seconds = Number(win.limit_window_seconds);
  return {
    usedPct: clampPct(usedPercent),
    remainingPct: clampPct(100 - usedPercent),
    seconds: Number.isFinite(seconds) ? seconds : null,
    resetHint: parseResetHint(win.reset_at),
    resetAt: parseResetTimeMs(win.reset_at),
    label: windowLabelFromSeconds(seconds),
    latent: isLatentWindow(win),
  };
}

function parseChatGPTUsage(usage     )               {
  const rl = usage?.rate_limit || {};
  const windows = [rl.primary_window, rl.secondary_window]
    .map(normalizeUsageWindow)
    .filter((w)                   => w !== null);

  if (!windows.length && usage?.spend_control?.individual_limit) {
    const lim = usage.spend_control.individual_limit;
    const usedPct = clampPct(Number(lim.used_percent));
    const remainingPct =
      lim.remaining_percent != null
        ? clampPct(Number(lim.remaining_percent))
        : usedPct == null
          ? null
          : clampPct(100 - usedPct);
    return {
      id: "chatgpt",
      name: "ChatGPT",
      plan: prettyChatPlan(usage?.plan_type),
      remainingPct,
      usedPct,
      windowLabel: "额度",
      resetHint: parseResetHint(lim.reset_at),
      resetAt: parseResetTimeMs(lim.reset_at),
      remaining5hPct: null,
      reset5hHint: null,
      reset5hAt: null,
      extra: "",
      url: URLS.chatgpt,
      ok: remainingPct != null,
    };
  }

  if (!windows.length) throw new Error("无法解析 ChatGPT 额度");

  const weekly =
    windows.find((w) => w.seconds != null && w.seconds >= 6 * 24 * 3600) ||
    windows.slice().sort((a, b) => (b.seconds || 0) - (a.seconds || 0))[0];
  const win5h = windows.find((w) => w !== weekly && w.seconds != null && w.seconds <= 24 * 3600);

  let remaining5hPct                = null;
  let reset5hHint                = null;
  let reset5hAt                = null;

  if (win5h) {
    remaining5hPct = win5h.remainingPct;
    if (win5h.usedPct === 0) {
      reset5hHint = "满";
      reset5hAt = null;
    } else {
      reset5hHint = win5h.resetHint;
      reset5hAt = win5h.resetAt;
    }
  }

  return {
    id: "chatgpt",
    name: "ChatGPT",
    plan: prettyChatPlan(usage?.plan_type),
    remainingPct: weekly.remainingPct,
    usedPct: weekly.usedPct,
    windowLabel: weekly.label,
    resetHint: weekly.resetHint,
    resetAt: weekly.resetAt,
    remaining5hPct,
    reset5hHint,
    reset5hAt,
    extra: win5h ? `${win5h.label}剩 ${Math.round(win5h.remainingPct || 0)}%` : "",
    url: URLS.chatgpt,
    ok: weekly.remainingPct != null,
  };
}

function bucketText(bucket     )         {
  return `${bucket.window || ""} ${bucket.bucketId || ""} ${bucket.id || ""} ${bucket.label || ""}`.toLowerCase();
}

function parseAntigravity(body     )               {
  const groups = Array.isArray(body?.groups) ? body.groups : [];
  const buckets        = [];
  for (const g of groups) {
    const groupName = g.displayName || g.display_name || "";
    for (const b of g.buckets || []) {
      const remaining = Number(b.remainingFraction ?? b.remaining_fraction);
      if (Number.isNaN(remaining)) continue;
      const remainingPct = clampPct(remaining <= 1 ? remaining * 100 : remaining);
      const bucketId = b.bucketId || b.bucket_id || "";
      buckets.push({
        id: `${bucketId} ${groupName} ${b.displayName || b.display_name || ""}`,
        remainingPct,
        usedPct: clampPct(100 - (remainingPct || 0)),
        resetHint: parseResetHint(b.resetTime || b.reset_time, b.description),
        resetAt: parseResetTimeMs(b.resetTime || b.reset_time, b.description),
        label: b.displayName || b.display_name || groupName || "额度",
        bucketId,
        window: String(b.window || "").toLowerCase(),
      });
    }
  }
  if (!buckets.length) throw new Error("无法解析 Google 额度");
  // A too-old client only receives the Claude/GPT group, which stays at 100%
  // while Gemini itself is partly used. Never substitute that group.
  const pool = buckets.filter((b) => /gemini/.test(bucketText(b)));
  if (!pool.length) throw new Error("响应里没有 Gemini 额度");
  const weekly =
    pool.find((b) => /week|weekly|7d|周/.test(bucketText(b))) ||
    pool[0];
  const bucket5h = pool.find(
    (b) => b !== weekly && (/5h|five[-_ ]?hour|hour|小时/.test(bucketText(b)) || b.bucketId === "gemini-5h")
  );

  let remaining5hPct                = null;
  let reset5hHint                = null;
  let reset5hAt                = null;

  if (bucket5h) {
    remaining5hPct = bucket5h.remainingPct;
    if (bucket5h.remainingPct != null && bucket5h.remainingPct >= 99.9) {
      reset5hHint = "满";
      reset5hAt = null;
    } else {
      reset5hHint = bucket5h.resetHint;
      reset5hAt = bucket5h.resetAt;
    }
  }

  return {
    id: "gemini",
    name: "Gemini",
    plan: "",
    remainingPct: weekly.remainingPct,
    usedPct: weekly.usedPct,
    windowLabel: "本周",
    resetHint: weekly.resetHint,
    resetAt: weekly.resetAt,
    remaining5hPct,
    reset5hHint,
    reset5hAt,
    extra: bucket5h ? `5小时剩 ${Math.round(bucket5h.remainingPct || 0)}%` : "",
    url: URLS.gemini,
    ok: weekly.remainingPct != null,
  };
}

// ---------- Fetchers ----------
function averageServices(services                                     )               {
  const ok = (services || []).filter(
    (s)                    => s != null && s.ok && s.remainingPct != null
  );
  if (!ok.length) throw new Error("无法解析额度");
  const remainingPct = clampPct(
    ok.reduce((sum, s) => sum + Number(s.remainingPct), 0) / ok.length
  );
  const bottleneck = ok.slice().sort((a, b) => (a.remainingPct || 0) - (b.remainingPct || 0))[0];
  const withReset = ok.filter((s) => s.resetAt != null && Number.isFinite(s.resetAt));
  const earliestReset = withReset.length
    ? withReset.slice().sort((a, b) => (a.resetAt || 0) - (b.resetAt || 0))[0]
    : bottleneck;

  const with5h = ok.filter((s) => s.remaining5hPct != null && Number.isFinite(s.remaining5hPct));
  let remaining5hPct                = null;
  let reset5hHint                = null;
  let reset5hAt                = null;

  if (with5h.length > 0) {
    remaining5hPct = clampPct(
      with5h.reduce((sum, s) => sum + Number(s.remaining5hPct), 0) / with5h.length
    );
    const activeCooldowns = with5h.filter(
      (s) => s.reset5hAt != null && Number.isFinite(s.reset5hAt) && s.reset5hHint !== "满"
    );
    if (activeCooldowns.length > 0) {
      const earliest5h = activeCooldowns.slice().sort((a, b) => (a.reset5hAt || 0) - (b.reset5hAt || 0))[0];
      reset5hHint = earliest5h.reset5hHint;
      reset5hAt = earliest5h.reset5hAt;
    } else {
      reset5hHint = "满";
    }
  }

  return Object.assign({}, bottleneck, {
    remainingPct,
    usedPct: remainingPct == null ? null : clampPct(100 - remainingPct),
    resetHint: earliestReset.resetHint || bottleneck.resetHint || "",
    resetAt: earliestReset.resetAt ?? bottleneck.resetAt ?? null,
    remaining5hPct,
    reset5hHint,
    reset5hAt,
    extra: bottleneck.extra || "",
    ok: remainingPct != null,
  });
}

async function fetchAveragedAccounts(
  files           ,
  testers          ,
  fetchOne                                          ,
  missingError
)                        {
  const accounts = findCpaFiles(files, testers);
  if (!accounts.length) throw new Error(missingError);
  const errors           = [];
  const settled = await Promise.all(
    accounts.map(async (file) => {
      try {
        const res = await fetchOne(file);
        return { ok: true, res, file };
      } catch (e     ) {
        errors.push(`${file.name || "account"}: ${e.message || e}`);
        return { ok: false, error: e, file };
      }
    })
  );
  const successful = settled.filter(
    (s)                                                      =>
      Boolean(s && s.ok && s.res && s.res.ok && s.res.remainingPct != null)
  );
  if (!successful.length) {
    throw new Error(errors[0] || missingError);
  }
  const result = averageServices(successful.map((s) => s.res));
  result.accountCount = successful.length;
  result.totalAccounts = accounts.length;
  result.accountDetails = successful.map((s) => ({
    name: s.file.name || s.file.account || s.file.email || "account",
    remainingPct: s.res.remainingPct,
    resetHint: s.res.resetHint,
    resetAt: s.res.resetAt,
    remaining5hPct: s.res.remaining5hPct,
    reset5hHint: s.res.reset5hHint,
    reset5hAt: s.res.reset5hAt,
    extra: s.res.extra,
  }));
  if (errors.length > 0 && errors.length < accounts.length) {
    result.warnings = errors;
  }
  return result;
}

async function fetchChatGPTAccount(cfg        , openai         )                        {
  const authIndex = authIndexOf(openai);
  if (authIndex == null) throw new Error("CPA 未找到 ChatGPT 认证");
  const accountId =
    openai.account_id ||
    openai.accountId ||
    openai.chatgpt_account_id ||
    openai.chatgptAccountId ||
    openai.id_token?.chatgpt_account_id ||
    openai.idToken?.chatgptAccountId ||
    "";
  const header                         = {
    Authorization: "Bearer $TOKEN$",
    Accept: "application/json",
  };
  if (accountId) header["ChatGPT-Account-Id"] = String(accountId);
  const resp = await cpaApiCall(cfg.cpaBaseUrl, cfg.cpaApiKey, {
    authIndex,
    method: "GET",
    url: "https://chatgpt.com/backend-api/wham/usage",
    header,
  });
  return parseChatGPTUsage(parseApiBody(resp));
}

async function fetchChatGPT(cfg        , files           )                        {
  if (!cfg.cpaApiKey || !cfg.cpaBaseUrl) {
    return emptyService("chatgpt", "ChatGPT", URLS.chatgpt, "未配置");
  }
  return fetchAveragedAccounts(
    files,
    [/openai/, /chatgpt/, /codex/],
    (file) => fetchChatGPTAccount(cfg, file),
    "CPA 未找到 ChatGPT 认证"
  );
}

async function fetchGeminiAccount(cfg        , ag         )                        {
  const authIndex = authIndexOf(ag);
  if (authIndex == null) throw new Error("CPA 未找到 Google 认证");
  const project = ag.project_id || ag.projectId || "";
  const resp = await cpaApiCall(cfg.cpaBaseUrl, cfg.cpaApiKey, {
    authIndex,
    method: "POST",
    url: "https://daily-cloudcode-pa.googleapis.com/v1internal:retrieveUserQuotaSummary",
    header: {
      Authorization: "Bearer $TOKEN$",
      "Content-Type": "application/json",
      "User-Agent": ANTIGRAVITY_UA,
    },
    data: JSON.stringify(project ? { project } : {}),
  });
  return parseAntigravity(parseApiBody(resp));
}

async function fetchGemini(cfg        , files           )                        {
  if (!cfg.cpaApiKey || !cfg.cpaBaseUrl) {
    return emptyService("gemini", "Gemini", URLS.gemini, "未配置");
  }
  return fetchAveragedAccounts(
    files,
    [/antigravity/, /gemini/],
    (file) => fetchGeminiAccount(cfg, file),
    "CPA 未找到 Google 认证"
  );
}

async function fetchAll(cfg        )                     {
  const errors           = [];
  let files            = [];
  if (cfg.cpaApiKey && cfg.cpaBaseUrl) {
    try {
      files = await listCpaFiles(cfg);
    } catch (e     ) {
      errors.push(`CPA: ${friendlyHttpError(e)}`);
    }
  }

  const jobs        = [
    ["chatgpt", () => fetchChatGPT(cfg, files), "ChatGPT", URLS.chatgpt],
    ["gemini", () => fetchGemini(cfg, files), "Gemini", URLS.gemini],
  ];

  const results = await Promise.all(
    jobs.map(async ([id, fn, name, url]) => {
      try {
        const service = await fn();
        const errs = service.warnings || [];
        return [id, service, errs.length ? `${name}: 部分账号获取失败 (${errs.join("; ")})` : null]         ;
      } catch (e     ) {
        const msg = friendlyHttpError(e);
        return [id, emptyService(id, name, url, msg), `${name}: ${msg}`]         ;
      }
    })
  );
  const services      = {};
  for (const [id, service, error] of results) {
    services[id] = service;
    if (error) errors.push(error);
  }

  return {
    fetchedAt: new Date().toISOString(),
    chatgpt: services.chatgpt,
    gemini: services.gemini,
    errors,
  };
}

// ---------- Scriptable host ----------
const CONFIG_KEY = "xp-toolkit.ai-quota.scriptable.config.v1";
const REFRESH_ACTION = "refresh-quota";
const FAMILIES = ["small", "medium", "large", "extraLarge", "extraLargePortrait",
  "accessoryRectangular", "accessoryInline", "accessoryCircular"];
const SERVICES = [["chatgpt", "ChatGPT"], ["gemini", "Gemini"]];
const SHORT_NAME = { chatgpt: "GPT", gemini: "Gemini" };
const REFRESH_MS = 15 * 60 * 1000;

async function loadJSON(url, opts = {}) {
  const request = new Request(url);
  request.method = opts.method || "GET";
  request.headers = { Accept: "application/json", "User-Agent": UA, ...opts.headers };
  if (opts.body != null) request.body = JSON.stringify(opts.body);
  request.timeoutInterval = 8;
  // Credentials belong to the configured management origin, not a redirect target.
  request.onRedirect = () => null;
  let text;
  try {
    text = await request.loadString();
  } catch (_) {
    if (!request.response?.statusCode) throw new Error("连接失败或超时");
  }
  const statusCode = request.response?.statusCode;
  if (!(statusCode >= 200 && statusCode < 300)) {
    const message = statusCode >= 300 && statusCode < 400 ? "CPA 管理地址发生重定向"
      : statusCode === 401 || statusCode === 403 ? "CPA 密钥无效或没有权限"
        : statusCode ? `CPA HTTP ${statusCode}` : "连接失败或超时";
    throw new Error(message);
  }
  try {
    return JSON.parse(text);
  } catch (_) {
    throw new Error("CPA 返回了无效 JSON");
  }
}

// The shared fetchers use this for user-facing errors. Never show upstream bodies,
// exception messages or account data returned as part of an error.
function friendlyHttpError(error) {
  if (error.statusCode === 401 || error.statusCode === 403) return "上游账号授权失败";
  if (error.statusCode === 429) return "上游请求太频繁";
  const message = String(error.message || "");
  if (["连接失败或超时", "CPA 密钥无效或没有权限", "CPA 管理地址发生重定向", "CPA 返回了无效 JSON"].includes(message)
    || /^CPA HTTP \d{3}$/.test(message)) return message;
  return "账号或额度暂不可用";
}

function readConfig() {
  if (!Keychain.contains(CONFIG_KEY)) return null;
  const cfg = JSON.parse(Keychain.get(CONFIG_KEY));
  if (!cfg || typeof cfg.cpaApiKey !== "string" || !cfg.cpaApiKey.trim()
    || !/^[\da-f-]{36}$/i.test(cfg.scope)) return null;
  const cpaBaseUrl = normalizeCpaBaseUrl(cfg.cpaBaseUrl);
  return cpaBaseUrl ? { ...cfg, cpaBaseUrl } : null;
}

function cachePath(fm, cfg) {
  return fm.joinPath(fm.libraryDirectory(), `xp-ai-quota-${cfg.scope}.json`);
}

function readCache(cfg) {
  try {
    const fm = FileManager.local();
    const path = cachePath(fm, cfg);
    if (!fm.fileExists(path)) return null;
    const entry = JSON.parse(fm.readString(path));
    return entry?.scope === cfg.scope && Number.isFinite(entry.checkedAt) && entry.services ? entry : null;
  } catch (_) {
    return null;
  }
}

function removeCache(cfg) {
  if (!cfg) return;
  const fm = FileManager.local();
  const path = cachePath(fm, cfg);
  if (fm.fileExists(path)) fm.remove(path);
}

async function loadQuota(cfg, force = false) {
  if (!cfg) return { state: "未配置", services: {} };
  const cached = readCache(cfg);
  const age = Date.now() - (cached?.checkedAt ?? 0);
  if (!force && cached && age >= 0 && age < CACHE_TTL_MS) return cached;

  const data = await fetchAll(cfg);
  if (readConfig()?.scope !== cfg.scope) return { state: "配置已变更", services: {} };
  const checkedAt = Date.now();
  const previous = readCache(cfg) ?? cached;
  const services = {};
  let freshCount = 0;
  let displayCount = 0;
  for (const [id] of SERVICES) {
    const result = data[id];
    if (result?.ok && Number.isFinite(result.remainingPct)) {
      const { warnings, ...quota } = result;
      services[id] = { ...quota, at: Date.parse(data.fetchedAt), partial: Boolean(warnings?.length) };
      freshCount++;
      displayCount++;
    } else if (previous?.services[id]?.ok) {
      services[id] = { ...previous.services[id], stale: true };
      displayCount++;
    }
  }
  const partial = Object.values(services).some((service) => service.partial);
  const state = freshCount === SERVICES.length && !partial ? "已更新" : freshCount ? "部分更新" : displayCount ? "缓存" : "暂不可用";
  const note = data.errors.find((message) => message.startsWith("CPA: "))?.slice(5);
  const snapshot = { scope: cfg.scope, checkedAt, state, services, freshCount, note };
  // Cache failed attempts too so the post-action render doesn't immediately fetch
  // again; the displayed timestamps above belong to each successful fetch only.
  try {
    const fm = FileManager.local();
    fm.writeString(cachePath(fm, cfg), JSON.stringify(snapshot));
  } catch (_) {
    return { ...snapshot, state: "缓存写入失败" };
  }
  return snapshot;
}

function ink() { return Color.dynamic(new Color("172034"), new Color("eef2ff")); }
function muted() { return Color.dynamic(new Color("556077"), new Color("a9b6cb")); }
function accent(id, pct) {
  if (pct <= 15) return Color.dynamic(new Color("b91c1c"), new Color("fda4af"));
  if (pct <= 35) return Color.dynamic(new Color("a04d04"), new Color("fcd34d"));
  const pairs = { chatgpt: ["047857", "6ee7b7"], gemini: ["254bc7", "93c5fd"] };
  const [light, dark] = pairs[id];
  return Color.dynamic(new Color(light), new Color(dark));
}

function text(parent, value, size, color = ink(), bold = false) {
  const node = parent.addText(value);
  node.font = bold ? Font.boldSystemFont(size) : Font.systemFont(size);
  node.textColor = color;
  node.lineLimit = 1;
  node.minimumScaleFactor = 0.75;
  return node;
}

function dateLabel(parent, ms, clock = false) {
  const node = parent.addDate(new Date(ms));
  if (clock) node.applyTimeStyle();
  else node.applyRelativeStyle();
  node.font = Font.systemFont(9);
  node.textColor = muted();
  node.lineLimit = 1;
  node.minimumScaleFactor = 0.75;
}

function bar(parent, id, pct, width, style = "linear") {
  if (!Number.isFinite(pct)) return;
  const color = accent(id, pct);
  const track = Color.dynamic(new Color("e1e8f2"), new Color("354157"));
  if (typeof parent.addProgress === "function") {
    const progress = parent.addProgress(pct, { style, progressColor: color, trackColor: track, thickness: 4 });
    progress.size = new Size(width, style === "linear" ? 4 : width);
    return progress;
  }
  // Older Scriptable: a linear stack still shows the actual fill, including 0%.
  if (style !== "linear") return null;
  const line = parent.addStack();
  line.size = new Size(width, 4);
  line.backgroundColor = track;
  line.cornerRadius = 2;
  if (pct > 0) {
    const fill = line.addStack();
    fill.size = new Size(width * pct / 100, 4);
    fill.backgroundColor = color;
    fill.cornerRadius = 2;
  }
  line.addSpacer();
}

function resetLine(parent, caption, at, hint) {
  const fallback = Number.isFinite(at) ? "待确认" : hint;
  const row = parent.addStack();
  row.centerAlignContent();
  row.spacing = 3;
  text(row, caption, 9, muted());
  if (at > Date.now()) dateLabel(row, at);
  else if (fallback) text(row, fallback, 9, muted());
}

function serviceLabel(name, quota) {
  return name + (quota?.stale ? " · 缓存" : quota?.partial ? " · 部分" : "");
}

function addColumn(parent, id, name, quota, accessory = false) {
  const col = parent.addStack();
  col.layoutVertically();
  col.spacing = accessory ? 1 : 4;
  text(col, accessory ? (SHORT_NAME[id] + (quota?.stale ? "*" : ""))
    : serviceLabel(name, quota), accessory ? 10 : 12, muted(), true);
  const pct = quota?.remainingPct;
  text(col, Number.isFinite(pct) ? `${pctLabel(pct)}%` : "—", accessory ? 15 : 25,
    Number.isFinite(pct) ? accent(id, pct) : muted(), true);
  bar(col, id, pct, accessory ? 52 : 92);
  if (!accessory) {
    if (!quota) text(col, "暂无数据", 9, muted());
    else resetLine(col, "重置", quota.resetAt, quota.resetHint);
    if (Number.isFinite(quota?.remaining5hPct)) {
      resetLine(col, `5h ${pctLabel(quota.remaining5hPct)}%`, quota.reset5hAt, quota.reset5hHint);
    }
  }
  return col;
}

function addSmallRow(parent, id, name, quota) {
  const row = parent.addStack();
  row.centerAlignContent();
  const left = row.addStack();
  left.layoutVertically();
  text(left, serviceLabel(name, quota), 11, ink(), true);
  const pct = quota?.remainingPct;
  if (Number.isFinite(quota?.remaining5hPct)) {
    resetLine(left, `5h ${pctLabel(quota.remaining5hPct)}%`, quota.reset5hAt, quota.reset5hHint);
  } else if (quota) resetLine(left, "重置", quota.resetAt, quota.resetHint);
  row.addSpacer(4);
  row.addSpacer();
  const right = row.addStack();
  right.layoutVertically();
  right.spacing = 2;
  const value = text(right, Number.isFinite(pct) ? `${pctLabel(pct)}%` : "—", 14,
    Number.isFinite(pct) ? accent(id, pct) : muted(), true);
  value.rightAlignText();
  bar(right, id, pct, 35);
}

function addAccounts(parent, snapshot, limit) {
  const groups = SERVICES.map(([id, name]) => (snapshot.services[id]?.accountDetails || []).map((detail) => ({ id, name, detail })));
  const total = groups.reduce((sum, group) => sum + group.length, 0);
  if (!total) return;
  parent.addSpacer(3);
  text(parent, total > limit ? `账号明细（显示 ${limit}/${total}）` : "账号明细", 10, muted(), true);
  // Interleave providers so a long account list never pushes other providers out.
  const details = [];
  for (let i = 0; details.length < Math.min(total, limit); i++) {
    for (const group of groups) if (group[i] && details.length < limit) details.push(group[i]);
  }
  for (const { id, name, detail } of details) {
    const row = parent.addStack();
    row.centerAlignContent();
    row.spacing = 4;
    text(row, `${name} · ${detail.name}`, 10, muted());
    row.addSpacer();
    if (Number.isFinite(detail.remaining5hPct)) text(row, `5h ${pctLabel(detail.remaining5hPct)}%`, 9, muted());
    if (detail.resetAt > Date.now()) dateLabel(row, detail.resetAt);
    const pct = detail.remainingPct;
    text(row, `${pctLabel(pct)}%`, 11, accent(id, pct), true);
  }
}

function renderWidget(snapshot, family, parameter = "", configured = true) {
  const widget = new ListWidget();
  widget.refreshAfterDate = new Date(Date.now() + REFRESH_MS);
  const state = snapshot.state;
  const services = snapshot.services;
  if (family === "accessoryInline") {
    const summary = SERVICES.map(([id]) => {
      const service = services[id];
      const label = SHORT_NAME[id];
      return `${label}${service?.stale ? "*" : ""} ${Number.isFinite(service?.remainingPct) ? `${pctLabel(service.remainingPct)}%` : "—"}`;
    });
    widget.addText(configured ? summary.join(" · ") : "AI Quota · 未配置");
    return widget;
  }
  if (family === "accessoryCircular") {
    const selected = SERVICES.find(([id]) => id === String(parameter).trim().toLowerCase());
    const available = SERVICES.filter(([id]) => Number.isFinite(services[id]?.remainingPct));
    available.sort(([a], [b]) => services[a].remainingPct - services[b].remainingPct);
    const [id] = selected || available[0] || SERVICES[0];
    const service = services[id];
    if (Number.isFinite(service?.remainingPct)) {
      const ring = bar(widget, id, service.remainingPct, 36, "circular");
      if (ring) text(ring, `${pctLabel(service.remainingPct)}%${service.stale ? "*" : ""}`, 10, ink(), true);
      else text(widget, `${pctLabel(service.remainingPct)}%`, 15, ink(), true);
      text(widget, SHORT_NAME[id], 8, muted(), true);
    } else text(widget, "AI —", 12, muted(), true);
    return widget;
  }
  if (family === "accessoryRectangular") {
    const row = widget.addStack();
    SERVICES.forEach(([id, name], i) => {
      if (i > 0) row.addSpacer();
      addColumn(row, id, name, services[id], true);
    });
    text(widget, state, 9, muted());
    return widget;
  }

  const small = family === "small";
  widget.backgroundColor = Color.dynamic(new Color("f5f8ff"), new Color("141c2c"));
  widget.setPadding(small ? 10 : 12, small ? 10 : 13, small ? 10 : 12, small ? 10 : 13);
  const panel = widget.addStack();
  panel.layoutVertically();
  panel.spacing = small ? 4 : 5;
  const header = panel.addStack();
  header.centerAlignContent();
  header.spacing = 4;
  text(header, "AI Quota", small ? 12 : 14, ink(), true);
  header.addSpacer();
  text(header, state, 9, muted());
  const at = Math.max(...Object.values(services).map((s) => s.at), 0);
  if (at) dateLabel(header, at, small);
  if (!configured) {
    text(panel, "请在 Scriptable 中运行脚本填写 CPA", 11, muted());
    widget.url = URLScheme.forRunningScript();
    return widget;
  }
  // On current Scriptable the card itself is the in-place refresh target.
  if (typeof panel.setAction === "function") {
    panel.setAction("刷新 AI 余量", { id: REFRESH_ACTION });
    text(header, "↻", 12, muted(), true);
  } else if (typeof header.addButton === "function") {
    header.addButton("刷新", { id: REFRESH_ACTION });
  } else {
    widget.url = URLScheme.forRunningScript();
  }

  panel.addSpacer();
  if (small) {
    SERVICES.forEach(([id, name], i) => {
      if (i > 0) panel.addSpacer();
      addSmallRow(panel, id, name, services[id]);
    });
  } else {
    const row = panel.addStack();
    row.topAlignContent();
    SERVICES.forEach(([id, name], i) => {
      if (i > 0) row.addSpacer();
      addColumn(row, id, name, services[id]);
    });
    if (family === "large" || family.startsWith("extraLarge")) addAccounts(panel, snapshot, family === "large" ? 5 : 8);
  }
  panel.addSpacer();
  if (snapshot.note && !small) text(panel, snapshot.note, 9, muted());
  return widget;
}

async function message(title, body) {
  const alert = new Alert();
  alert.title = title;
  alert.message = body;
  alert.addAction("好");
  await alert.presentAlert();
}

async function editConfig(previous) {
  const alert = new Alert();
  alert.title = "配置 CPA";
  alert.message = "仅填管理协议、主机和端口。公网请使用 HTTPS。旧密钥不会显示；同一地址留空则保留原密钥。";
  alert.addTextField("https://cpa.example:50442", previous?.cpaBaseUrl || "");
  alert.addSecureTextField("CPA 管理 API Key");
  alert.addAction("保存");
  alert.addCancelAction("取消");
  if (await alert.presentAlert() !== 0) return;
  let cpaBaseUrl;
  try {
    cpaBaseUrl = normalizeCpaBaseUrl(alert.textFieldValue(0));
  } catch (error) {
    return message("地址未保存", error.message);
  }
  const cpaApiKey = alert.textFieldValue(1).trim() || (cpaBaseUrl === previous?.cpaBaseUrl ? previous.cpaApiKey : "");
  if (!cpaBaseUrl || !cpaApiKey) return message("配置未保存", "请输入 CPA 地址和管理 Key；修改地址时必须重新输入 Key。");
  if (cpaBaseUrl !== previous?.cpaBaseUrl || cpaApiKey !== previous?.cpaApiKey) {
    Keychain.set(CONFIG_KEY, JSON.stringify({ cpaBaseUrl, cpaApiKey, scope: UUID.string() }));
    removeCache(previous);
  }
  await message("配置已保存", "再运行脚本可测试连接或预览组件；桌面组件会使用新配置。旧组件快照可能会保留到系统重新渲染。");
}

async function runInApp(cfg) {
  if (!cfg) return editConfig(null);
  const menu = new Alert();
  menu.title = "AI Quota";
  menu.message = "检查 CPA 连接、预览小组件或修改配置。";
  const actions = ["测试连接并刷新", "预览小号", "预览中号", "预览大号", "修改 CPA 配置", "清除配置和缓存"];
  actions.forEach((label) => menu.addAction(label));
  menu.addCancelAction("取消");
  const action = await menu.presentAlert();
  if (action === 0) {
    const snapshot = await loadQuota(cfg, true);
    return message(snapshot.state, snapshot.note || `成功读取 ${snapshot.freshCount ?? 0}/${SERVICES.length} 个服务。`);
  }
  if (action >= 1 && action <= 3) {
    const family = FAMILIES[action - 1];
    const widget = renderWidget(await loadQuota(cfg), family);
    await widget[`present${family[0].toUpperCase()}${family.slice(1)}`]();
  }
  if (action === 4) return editConfig(cfg);
  if (action === 5) {
    const confirm = new Alert();
    confirm.title = "清除 CPA 配置和本机缓存？";
    confirm.addDestructiveAction("清除");
    confirm.addCancelAction("取消");
    if (await confirm.presentAlert() === 0) {
      removeCache(cfg);
      Keychain.remove(CONFIG_KEY);
    }
  }
}

async function main() {
  const cfg = readConfig();
  if (args.widgetAction?.id === REFRESH_ACTION) {
    // The action and the subsequent render are separate Scriptable runs.
    await loadQuota(cfg, true);
    return;
  }
  if (args.widgetAction) return;
  if (config.runsInWidget) {
    const family = FAMILIES.includes(config.widgetFamily) ? config.widgetFamily : "medium";
    Script.setWidget(renderWidget(await loadQuota(cfg), family, args.widgetParameter, Boolean(cfg)));
  } else if (config.runsInApp) {
    await runInApp(cfg);
  }
}

try {
  await main();
} catch (_) {
  if (args.widgetAction?.id === REFRESH_ACTION) throw new Error("AI Quota 刷新失败");
  if (config.runsInWidget) {
    const widget = new ListWidget();
    widget.addText("AI Quota 暂不可用");
    widget.refreshAfterDate = new Date(Date.now() + REFRESH_MS);
    Script.setWidget(widget);
  } else if (config.runsInApp) {
    await message("AI Quota 暂不可用", "请检查 Scriptable 本机存储权限后重试。");
  }
} finally {
  Script.complete();
}
